package android.widget;public class Switch extends CompoundButton {public Float visualPosition;public android.graphics.drawable.Drawable getThumbDrawable(){return thumb;}protected void onDraw(android.graphics.Canvas canvas){float d=getResources().getDisplayMetrics().density;float x=(getWidth()-36*d)/2;float position=visualPosition==null?(isChecked()?1:0):visualPosition;thumb.bounds.left=Math.round(x+18*d*position);thumb.bounds.right=thumb.bounds.left+Math.round(18*d);}public Object thumbTint,trackTint;public boolean showText,splitTrack;public android.graphics.drawable.Drawable track,thumb;public int switchWidth;public Switch(android.content.Context c){super(c);}public void setShowText(boolean b){showText=b;}public void setSplitTrack(boolean b){splitTrack=b;}public void setThumbTintList(Object o){thumbTint=o;}public void setTrackTintList(Object o){trackTint=o;}public void setTrackDrawable(android.graphics.drawable.Drawable d){track=d;}public void setThumbDrawable(android.graphics.drawable.Drawable d){thumb=d;}public void setSwitchMinWidth(int n){switchWidth=n;}public void setSwitchPadding(int n){}public void setThumbTextPadding(int n){} }
